import AppIntents
import SwiftUI
#if canImport(UIKit)
import UIKit
#endif

/// The app's own SF Symbols-style symbols, in `Assets.xcassets` as symbol image sets. They take
/// `.font`, `.imageScale`, weights and tints like system symbols. Generated by
/// `Scripts/Symbols/make_minidisc_symbol.py`.
nonisolated enum MinidiscSymbol {
    /// Albums: a MiniDisc, after the 💽 emoji.
    static let album = "minidisc"
    /// Albums, filled, for places that use filled symbols.
    static let albumFill = "minidisc.fill"
    /// Go to Album in song menus, context menus and the player's menu, on the iPhone and the Mac.
    static let goToAlbum = album

    /// Whether `name` is one of these rather than a system symbol.
    static func isCustom(_ name: String) -> Bool {
        name == album || name == albumFill
    }
}

extension Image {
    /// A system symbol, or one of the app's own (`MinidiscSymbol`), for views that take a symbol name.
    init(symbol name: String) {
        if MinidiscSymbol.isCustom(name) {
            self.init(name)
        } else {
            self.init(systemName: name)
        }
    }
}

extension Label where Title == Text, Icon == Image {
    /// `Label(_:systemImage:)` that also takes the app's own symbols.
    @_disfavoredOverload
    init(_ title: some StringProtocol, symbol name: String) {
        self.init { Text(title) } icon: { Image(symbol: name) }
    }

    /// `Label(_:systemImage:)` that also takes the app's own symbols.
    init(_ titleKey: LocalizedStringKey, symbol name: String) {
        self.init { Text(titleKey) } icon: { Image(symbol: name) }
    }
}

extension DisplayRepresentation.Image {
    /// A system symbol, or one of the app's own (`MinidiscSymbol`), for App Intents entities.
    nonisolated static func symbol(_ name: String) -> DisplayRepresentation.Image {
        MinidiscSymbol.isCustom(name) ? .init(named: name, isTemplate: true) : .init(systemName: name)
    }
}

#if canImport(UIKit)
extension UIImage {
    /// A system symbol, or one of the app's own (`MinidiscSymbol`), for UIKit and CarPlay.
    static func symbol(_ name: String) -> UIImage? {
        MinidiscSymbol.isCustom(name) ? UIImage(named: name) : UIImage(systemName: name)
    }
}
#endif
